class CBTInserter {
    TreeNode* root;
    deque<TreeNode*> dq;
public:
    CBTInserter(TreeNode* root) : root(root) {
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            TreeNode* curr = q.front(); q.pop();
            if (!curr->left || !curr->right) dq.push_back(curr);
            if (curr->left) q.push(curr->left);
            if (curr->right) q.push(curr->right);
        }
    }

    int insert(int val) {
        TreeNode* node = new TreeNode(val);
        TreeNode* parent = dq.front();
        if (!parent->left) {
            parent->left = node;
        } else {
            parent->right = node;
            dq.pop_front();
        }
        dq.push_back(node);
        return parent->val;
    }

    TreeNode* get_root() {
        return root;
    }
};

